// File: breadcrumb\script.js
document.querySelectorAll('.breadcrumb[data-breadcrumb-content]').forEach(breadcrumb => {
    const symbol = breadcrumb.dataset.breadcrumbContent;

    if(breadcrumb.querySelector('.breadcrumb-item')){
        breadcrumb.querySelectorAll('.breadcrumb-item:not(:last-child)').forEach(item => {
            item.dataset.breadcrumbContent = symbol;
        });
    }
    else if(breadcrumb.querySelector('li')){
        breadcrumb.querySelectorAll('li:not(:last-child)').forEach(item => {
            item.dataset.breadcrumbContent = symbol;
        });
    }
});

document.querySelectorAll('.breadcrumb[data-breadcrumb-content-image]').forEach(breadcrumb => {
    const imageUrl = breadcrumb.dataset.breadcrumbContentImage;
    const imageSize = breadcrumb.dataset.breadcrumbContentImageSize;

    if(breadcrumb.querySelector('.breadcrumb-item')){
        breadcrumb.querySelectorAll('.breadcrumb-item:not(:last-child)').forEach(item => {
            item.style.setProperty('--breadcrumb-content-image', `url(${imageUrl})`);
            item.style.setProperty('--breadcrumb-content-image-size', imageSize);
        });
    }
    else if(breadcrumb.querySelector('li')){
        breadcrumb.querySelectorAll('li:not(:last-child)').forEach(item => {
            item.style.setProperty('--breadcrumb-content-image', `url(${imageUrl})`);
            item.style.setProperty('--breadcrumb-content-image-size', imageSize);
        });
    }
});

