// File: dropdown\script.js
class Dropdown {
    constructor() {
        this.dropdowns = document.querySelectorAll('.dropdown');
        this.init();
    }

    init() {
        this.dropdowns.forEach(dropdown => {
            const box = dropdown.querySelector('.dropdown-box');
            const menu = dropdown.querySelector('.dropdown-menu');
            const submenus = dropdown.querySelectorAll('.dropdown-submenu');
            const isHover = dropdown.classList.contains('dropdown-hover') || 
                            (menu && menu.classList.contains('dropdown-hover'));

            if (!box) return;

            // Click on main dropdown box (if hover not enabled)
            if (!isHover) {
                box.addEventListener('click', (e) => {
                    e.stopPropagation();
                    this.toggleDropdown(dropdown);
                });
            }

            // Submenus
            submenus.forEach(submenu => {
                const toggle = submenu.querySelector('.dropdown-submenu-toggle');
                if (!isHover && toggle) {
                    toggle.addEventListener('click', (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                        this.toggleSubmenu(submenu);
                    });
                }

                // Hover (desktop only)
                submenu.addEventListener('mouseenter', () => {
                    if (window.innerWidth > 768 && isHover) {
                        this.openSubmenu(submenu);
                    }
                });
                submenu.addEventListener('mouseleave', () => {
                    if (window.innerWidth > 768 && isHover) {
                        this.closeSubmenu(submenu);
                    }
                });
            });

            // Click outside closes dropdown
            if (!isHover) {
                document.addEventListener('click', (e) => {
                    if (!dropdown.contains(e.target)) {
                        this.closeDropdown(dropdown);
                    }
                });
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'Escape') this.closeDropdown(dropdown);
                });
            }
        });
    }

    toggleDropdown(currentDropdown) {
        // Close all other dropdowns
        this.dropdowns.forEach(dropdown => {
            if (dropdown !== currentDropdown) {
                dropdown.classList.remove('active');
                dropdown.querySelectorAll('.dropdown-submenu').forEach(sub => this.closeSubmenu(sub));
            }
        });
        // Toggle current
        currentDropdown.classList.toggle('active');
    }

    closeDropdown(dropdown) {
        dropdown.classList.remove('active');
        dropdown.querySelectorAll('.dropdown-submenu').forEach(sub => this.closeSubmenu(sub));
    }

    toggleSubmenu(submenu) {
        if (submenu.classList.contains('active')) this.closeSubmenu(submenu);
        else this.openSubmenu(submenu);
    }

    openSubmenu(submenu) {
        // Close siblings
        const siblings = Array.from(submenu.parentElement.children)
            .filter(child => child !== submenu && child.classList.contains('dropdown-submenu'));
        siblings.forEach(s => this.closeSubmenu(s));
        submenu.classList.add('active');
    }

    closeSubmenu(submenu) {
        submenu.classList.remove('active');
        submenu.querySelectorAll('.dropdown-submenu').forEach(child => this.closeSubmenu(child));
    }
}

new Dropdown();

