// File: page-indicator\script.js
class PageIndicator {
    constructor() {
        this.indicators = document.querySelectorAll('.page-indicator');
        this.init();
    }

    init() {
        this.indicators.forEach(indicator => {
            this.setupIndicator(indicator);
        });
    }

    setupIndicator(indicator) {
        const pages = indicator.querySelectorAll('.page');
        pages.forEach(page => {
            this.setupPageClick(page, pages);
        });
    }

    setupPageClick(page, allPages) {
        page.addEventListener('click', () => {
            this.activatePage(page, allPages);
        });
    }

    activatePage(selectedPage, allPages) {
        allPages.forEach(page => page.classList.remove('active'));
        selectedPage.classList.add('active');
    }
}

new PageIndicator();

document.querySelectorAll('.page-indicator[data-page-indicator-size]').forEach(pageIndicator => {
    const pageIndicatorSize = pageIndicator.dataset.pageIndicatorSize;
    pageIndicator.style.setProperty('--page-indicator-size', pageIndicatorSize);
});

// File: progress\script.js
document.querySelectorAll('.progress-bar').forEach(progressBar => {
    const dataMap = {
        '--progress-percentage': progressBar.dataset.progressPercentage,
        '--progress-content-place': progressBar.dataset.progressContentPlace,
        '--progress-animation-delay': progressBar.dataset.progressAnimationDelay,
        '--progress-animation-duration': progressBar.dataset.progressAnimationDuration
    };

    for (const [cssVar, value] of Object.entries(dataMap)) {
        if (value !== undefined) {
            progressBar.style.setProperty(cssVar, value);
        }
    }
});

