// File: waiting-indicator\script.js
document.querySelectorAll('[class*="loader-"]').forEach(loader => {
    const loaderClass = Array.from(loader.classList).find(c => c.startsWith('loader-'));
    if (!loaderClass) return;
    const loaderName = loaderClass.replace('loader-', '');
    const dataAttrName = `loader-${loaderName}-size`;
    const value = loader.dataset[dataAttrName.replace(/-([a-z])/g, (_, char) => char.toUpperCase())];
    if (!value) return;
    const cssVarName = `--loader-${loaderName}-size`;
    loader.style.setProperty(cssVarName, value);
});
